  open = 50,
  /* how far the swell carries into its neighbours, 0..100 */
  reach = 35,
  /* the spring, 0..100 — see springOf in ./spring */
  bounce = 10,
  /* the air between pictures, in px. The corner follows it. */
  gap = 8,
