    const hside = axis === 0 ? A.hh : A.hw;
    front = A.x * fnx + A.y * fny + hmain;
    if (axis === 0) { snx = -sA; sny = cA; negE = E3; posE = E1; } else { snx = cA; sny = sA; negE = E2; posE = E4; }
