    const hside = axis === 2 ? B.hh : B.hw;
    front = B.x * fnx + B.y * fny + hmain;
    if (axis === 2) { snx = -sB; sny = cB; negE = E3; posE = E1; } else { snx = cB; sny = sB; negE = E2; posE = E4; }
